<?php
use Illuminate\Support\Facades\Route;
use App\Http\Controllers\{AuthController,DashboardController,UnitController,AssetController,AlertController,IncidentController,IntegrationController,ModuleController,AdminController,MaintenanceController};
Route::get('/login',[AuthController::class,'login'])->name('login')->middleware('guest');
Route::post('/login',[AuthController::class,'authenticate'])->name('login.post')->middleware('guest');
Route::post('/logout',[AuthController::class,'logout'])->name('logout')->middleware('auth');
Route::middleware(['auth','permission:dashboard.view'])->group(function(){
 Route::get('/',[DashboardController::class,'index'])->name('dashboard');
 Route::get('/tv',[DashboardController::class,'tv'])->name('tv');
 Route::get('/unidades',[UnitController::class,'index'])->name('units.index')->middleware('permission:units.view');
 Route::get('/unidades/{unit}',[UnitController::class,'show'])->name('units.show')->middleware('permission:units.view');
 Route::post('/unidades',[UnitController::class,'store'])->name('units.store')->middleware('permission:units.manage');
 Route::put('/unidades/{unit}',[UnitController::class,'update'])->name('units.update')->middleware('permission:units.manage');
 Route::get('/ativos',[AssetController::class,'index'])->name('assets.index')->middleware('permission:assets.view');
 Route::post('/ativos',[AssetController::class,'store'])->name('assets.store')->middleware('permission:assets.manage');
 Route::put('/ativos/{asset}',[AssetController::class,'update'])->name('assets.update')->middleware('permission:assets.manage');
 Route::post('/ativos/{asset}/transferencia',[AssetController::class,'transfer'])->name('assets.transfer')->middleware('permission:assets.manage');
 Route::get('/alertas',[AlertController::class,'index'])->name('alerts.index')->middleware('permission:alerts.view');
 Route::post('/alertas/{alert}/reconhecer',[AlertController::class,'acknowledge'])->name('alerts.ack')->middleware('permission:alerts.manage');
 Route::post('/alertas/{alert}/silenciar',[AlertController::class,'mute'])->name('alerts.mute')->middleware('permission:alerts.manage');
 Route::post('/alertas/{alert}/resolver',[AlertController::class,'resolve'])->name('alerts.resolve')->middleware('permission:alerts.manage');
 Route::get('/incidentes',[IncidentController::class,'index'])->name('incidents.index')->middleware('permission:incidents.view');
 Route::post('/incidentes',[IncidentController::class,'store'])->name('incidents.store')->middleware('permission:incidents.manage');
 Route::get('/incidentes/{incident}',[IncidentController::class,'show'])->name('incidents.show')->middleware('permission:incidents.view');
 Route::post('/incidentes/{incident}/estado',[IncidentController::class,'status'])->name('incidents.status')->middleware('permission:incidents.manage');
 Route::post('/incidentes/{incident}/responsavel',[IncidentController::class,'assign'])->name('incidents.assign')->middleware('permission:incidents.manage');
 Route::post('/incidentes/{incident}/comentarios',[IncidentController::class,'comment'])->name('incidents.comment')->middleware('permission:incidents.manage');
 Route::get('/integracoes',[IntegrationController::class,'index'])->name('integrations.index')->middleware('permission:integrations.view');
 Route::get('/integracoes/{integration}',[IntegrationController::class,'show'])->name('integrations.show')->middleware('permission:integrations.view');
 Route::put('/integracoes/{integration}',[IntegrationController::class,'update'])->name('integrations.update')->middleware('permission:integrations.manage');
 Route::post('/integracoes/{integration}/teste',[IntegrationController::class,'test'])->name('integrations.test')->middleware('permission:integrations.manage');
 Route::post('/integracoes/{integration}/sincronizar',[IntegrationController::class,'sync'])->name('integrations.sync')->middleware('permission:integrations.manage');
 Route::get('/modulos/{section}',[ModuleController::class,'show'])->name('modules.show')->whereIn('section',['operations','network','wan','wifi','servers','tickets','security','backups','reports','audit','health','notifications']);
 Route::get('/centro-operacoes',fn()=>redirect()->route('modules.show','operations'))->name('modules.operations');
 Route::get('/rede',fn()=>redirect()->route('modules.show','network'))->name('modules.network');
 Route::get('/wan',fn()=>redirect()->route('modules.show','wan'))->name('modules.wan');
 Route::get('/wifi',fn()=>redirect()->route('modules.show','wifi'))->name('modules.wifi');
 Route::get('/servidores',fn()=>redirect()->route('modules.show','servers'))->name('modules.servers');
 Route::get('/chamados',fn()=>redirect()->route('modules.show','tickets'))->name('modules.tickets');
 Route::get('/seguranca',fn()=>redirect()->route('modules.show','security'))->name('modules.security');
 Route::get('/backups',fn()=>redirect()->route('modules.show','backups'))->name('modules.backups');
 Route::get('/relatorios',fn()=>redirect()->route('modules.show','reports'))->name('modules.reports');
 Route::get('/auditoria',fn()=>redirect()->route('modules.show','audit'))->name('modules.audit');
 Route::get('/saude',fn()=>redirect()->route('modules.show','health'))->name('modules.health');
 Route::get('/notificacoes',fn()=>redirect()->route('modules.show','notifications'))->name('modules.notifications');
 Route::get('/relatorios/incidentes.csv',[ModuleController::class,'csv'])->name('reports.csv')->middleware('permission:reports.view');
 Route::post('/notificacoes/{id}/lida',[ModuleController::class,'markRead'])->name('notifications.read')->middleware('permission:notifications.view');
 Route::get('/usuarios',[AdminController::class,'users'])->name('admin.users')->middleware('permission:users.manage');
 Route::post('/usuarios',[AdminController::class,'createUser'])->name('admin.users.store')->middleware('permission:users.manage');
 Route::put('/usuarios/{user}',[AdminController::class,'updateUser'])->name('admin.users.update')->middleware('permission:users.manage');
 Route::get('/manutencoes',[MaintenanceController::class,'index'])->name('maintenance.index')->middleware('permission:alerts.manage');
 Route::post('/manutencoes',[MaintenanceController::class,'store'])->name('maintenance.store')->middleware('permission:alerts.manage');
 Route::delete('/manutencoes/{id}',[MaintenanceController::class,'delete'])->name('maintenance.delete')->middleware('permission:alerts.manage');
 Route::get('/configuracoes',[AdminController::class,'settings'])->name('admin.settings')->middleware('permission:settings.manage');
 Route::post('/configuracoes/reset-demo',[AdminController::class,'resetDemo'])->name('admin.demo.reset')->middleware('permission:settings.manage');
});
